    let t_audio_buffer = audio_buffer::template::<D>(scope, None, &options);
    st.set_template(ids::AUDIO_BUFFER, scope, t_audio_buffer);
    let t_audio_listener = audio_listener::template::<D>(scope, None, &options);
    st.set_template(ids::AUDIO_LISTENER, scope, t_audio_listener);
